//! Trickplay tile sheets: the seek bar thumbnails generated by the server.

use crate::{ItemId, MediaSourceId, Result, Session};

impl Session {
    /// Downloads tile sheet `index` of the trickplay thumbnails `width`
    /// pixels wide of `media_source` of `item`
    /// (`GET Videos/{id}/Trickplay/{width}/{index}.jpg`), as JPEG bytes.
    ///
    /// The widths an item offers are in [`crate::BaseItemDto::trickplay_for`].
    pub async fn trickplay_sheet(
        &self,
        item: &ItemId,
        media_source: &MediaSourceId,
        width: u32,
        index: u32,
    ) -> Result<Vec<u8>> {
        self.server()
            .http()
            .get_bytes(
                Some(self.token()),
                &format!("Videos/{item}/Trickplay/{width}/{index}.jpg"),
                &[("mediaSourceId", media_source.to_string())],
            )
            .await
    }
}
